function distinctIntegers(n) {
  // 1 % i is never 1, so a lone 1 adds nothing.
  if (n === 1) {
    return 1;
  }
  // Every x >= 3 adds x - 1, because x % (x - 1) === 1.
  // That chain fills in n - 1, n - 2, ..., down to 2.
  // The number 1 is never added, since x % 1 === 0.
  const smallest = 2;
  const largest = n;
  return largest - smallest + 1;
}

