function distinctIntegers(n) {
  const board = new Set([n]);
  let changed = true;
  while (changed) {
    changed = false;
    for (const x of [...board]) {
      for (let i = 1; i <= n; i++) {
        if (x % i === 1 && !board.has(i)) {
          board.add(i);
          changed = true;
        }
      }
    }
  }
  return board.size;
}

